WITH with_last AS (SELECT s.*, latest.employee_level, latest.job_title FROM departments s LEFT JOIN LATERAL (SELECT c.level AS employee_level, c.job_title FROM employees c WHERE c.dept_id = s.id ORDER BY c.hire_date DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT id, dept_name, location, employee_level, CASE WHEN dept_name RLIKE '^(Sales|Marketing)$' THEN 'CORE' WHEN dept_name RLIKE '^(Engineering|HR)$' THEN 'PRIORITY' ELSE 'GROUP_A' END AS dept_name_zone FROM with_last ORDER BY dept_name DESC, dept_name_zone ASC;
